class SuperAdminDashboardScreen extends StatefulWidget{const SuperAdminDashboardScreen({super.key,this.repository});final SuperAdminRepository? repository;@override State<SuperAdminDashboardScreen> createState()=>_S();}class _S extends State<SuperAdminDashboardScreen>{late final repo=widget.repository??SuperAdminRepository();late Future<AdminDashboardSummary> f=repo.getDashboardSummary();@override Widget build(BuildContext context)=>FutureBuilder(future:f,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const LoadingView();if(s.hasError)return ErrorView(title:'Unable to load',message:s.error.toString(),onRetry:()=>setState(()=>f=repo.getDashboardSummary()));final d=s.data??const AdminDashboardSummary();return RefreshIndicator(onRefresh:()async=>setState(()=>f=repo.getDashboardSummary()),child:ListView(padding:const EdgeInsets.all(16),children:[Wrap(spacing:12,runSpacing:12,children:[_card('Total Users',d.totalUsers),_card('Active Users',d.activeUsers),_card('Inactive Users',d.inactiveUsers+d.suspendedUsers),_card('Total Masjids',d.totalMasjids),_card('Pending Requests',d.pendingRequests),_card('Approved Requests',d.approvedRequests),_card('Rejected Requests',d.rejectedRequests)]),const SizedBox(height:20),Wrap(spacing:12,children:[FilledButton(onPressed:()=>context.go('/super-admin/requests'),child:const Text('Masjid Requests')),FilledButton(onPressed:()=>context.go('/super-admin/masjids'),child:const Text('Masjids')),FilledButton(onPressed:()=>context.go('/super-admin/users'),child:const Text('Users'))]) ]));});Widget _card(String t,int v)=>SizedBox(width:190,child:Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(t),const SizedBox(height:8),Text('$v',style:const TextStyle(fontSize:28,fontWeight:FontWeight.bold))]))));}
